import{_ as t,c as o,o as i,ax as a}from"./chunks/framework.DHqKNX4U.js";const p=JSON.parse('{"title":"Job Queue Service","description":"","frontmatter":{},"headers":[],"relativePath":"services/job-queue.md","filePath":"services/job-queue.md"}'),s={name:"services/job-queue.md"};function n(r,e,c,d,l,h){return i(),o("div",null,e[0]||(e[0]=[a(`<h1 id="job-queue-service" tabindex="-1">Job Queue Service <a class="header-anchor" href="#job-queue-service" aria-label="Permalink to &quot;Job Queue Service&quot;">​</a></h1><p>This document describes the architecture of the job queue system, including the sync cycle coordination mechanism and relevant configuration options.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><p>The job queue system is built on <a href="https://docs.bullmq.io/" target="_blank" rel="noreferrer">BullMQ</a> backed by Redis (Valkey). Two worker processes run independently:</p><ul><li><strong>Ingestion worker</strong> (<code>ingestion.worker.ts</code>) — processes the <code>ingestion</code> queue</li><li><strong>Indexing worker</strong> (<code>indexing.worker.ts</code>) — processes the <code>indexing</code> queue</li></ul><h3 id="queues" tabindex="-1">Queues <a class="header-anchor" href="#queues" aria-label="Permalink to &quot;Queues&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Queue</th><th>Jobs</th><th>Purpose</th></tr></thead><tbody><tr><td><code>ingestion</code></td><td><code>schedule-continuous-sync</code>, <code>continuous-sync</code>, <code>initial-import</code>, <code>process-mailbox</code>, <code>sync-cycle-finished</code></td><td>Email ingestion and sync orchestration</td></tr><tr><td><code>indexing</code></td><td><code>index-email-batch</code></td><td>Meilisearch document indexing</td></tr></tbody></table><h3 id="job-flow" tabindex="-1">Job Flow <a class="header-anchor" href="#job-flow" aria-label="Permalink to &quot;Job Flow&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[schedule-continuous-sync] (repeating cron)</span></span>
<span class="line"><span>    └→ [continuous-sync] (per ingestion source)</span></span>
<span class="line"><span>           └→ [process-mailbox] × N (one per user mailbox)</span></span>
<span class="line"><span>                  └→ [index-email-batch] (batched, on indexing queue)</span></span>
<span class="line"><span>                  └→ [sync-cycle-finished] (dispatched by the last mailbox job)</span></span></code></pre></div><p>For initial imports, <code>initial-import</code> triggers the same <code>process-mailbox</code> → <code>sync-cycle-finished</code> flow.</p><h2 id="sync-cycle-coordination" tabindex="-1">Sync Cycle Coordination <a class="header-anchor" href="#sync-cycle-coordination" aria-label="Permalink to &quot;Sync Cycle Coordination&quot;">​</a></h2><p>Sync cycle completion (knowing when all mailboxes in a sync have finished) is coordinated via the <code>sync_sessions</code> PostgreSQL table rather than BullMQ&#39;s built-in flow/parent-child system.</p><p><strong>Why:</strong> BullMQ&#39;s <code>FlowProducer</code> stores the entire parent/child relationship in Redis atomically. For large tenants with thousands of mailboxes, this creates large Redis writes and requires loading all child job return values into memory at once for aggregation.</p><p><strong>How it works:</strong></p><ol><li>When <code>initial-import</code> or <code>continuous-sync</code> starts, it creates a <code>sync_sessions</code> row with <code>total_mailboxes = N</code>.</li><li>Each <code>process-mailbox</code> job atomically increments <code>completed_mailboxes</code> or <code>failed_mailboxes</code> when it finishes, and merges its <code>SyncState</code> into <code>ingestion_sources.sync_state</code> using PostgreSQL&#39;s <code>||</code> jsonb operator.</li><li>The job that brings <code>completed + failed</code> to equal <code>total</code> dispatches the <code>sync-cycle-finished</code> job.</li><li><code>sync-cycle-finished</code> reads the aggregated results from the session row and finalizes the source status.</li><li>The session row is deleted after finalization.</li></ol><h3 id="session-heartbeat" tabindex="-1">Session Heartbeat <a class="header-anchor" href="#session-heartbeat" aria-label="Permalink to &quot;Session Heartbeat&quot;">​</a></h3><p>Each <code>process-mailbox</code> job updates <code>last_activity_at</code> on the session every time it flushes an email batch to the indexing queue. This prevents the stale session detector from treating an actively processing large mailbox as stuck.</p><h3 id="stale-session-detection" tabindex="-1">Stale Session Detection <a class="header-anchor" href="#stale-session-detection" aria-label="Permalink to &quot;Stale Session Detection&quot;">​</a></h3><p>The <code>schedule-continuous-sync</code> job runs <code>SyncSessionService.cleanStaleSessions()</code> on every tick. A session is considered stale when <code>last_activity_at</code> has not been updated for 30 minutes, indicating the worker that created it has crashed before all mailbox jobs were enqueued.</p><p>When a stale session is detected:</p><ol><li>The associated ingestion source is set to <code>status: &#39;error&#39;</code> with a descriptive message.</li><li>The session row is deleted.</li><li>On the next scheduler tick, the source is picked up as an <code>error</code> source and a new <code>continuous-sync</code> job is dispatched.</li></ol><p>Already-ingested emails from the partial sync are preserved. The next sync skips them via duplicate detection (<code>checkDuplicate()</code>).</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Environment Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>SYNC_FREQUENCY</code></td><td><code>* * * * *</code></td><td>Cron pattern for continuous sync scheduling</td></tr><tr><td><code>INGESTION_WORKER_CONCURRENCY</code></td><td><code>5</code></td><td>Number of <code>process-mailbox</code> jobs that run in parallel</td></tr><tr><td><code>INGESTION_EMAIL_CONCURRENCY</code></td><td><code>3</code></td><td>Emails archived at once within one mailbox</td></tr><tr><td><code>INDEXING_WORKER_CONCURRENCY</code></td><td><code>4</code></td><td>Number of indexing jobs that run in parallel</td></tr><tr><td><code>MEILI_INDEXING_BATCH</code></td><td><code>500</code></td><td>Number of emails per <code>index-email-batch</code> job</td></tr><tr><td><code>MEILI_INDEXING_CHUNK</code></td><td><code>25</code></td><td>Documents built and sent to Meilisearch at a time</td></tr><tr><td><code>INDEXING_MAX_TEXT_BYTES</code></td><td><code>1000000</code></td><td>Extracted text kept per attachment and per body</td></tr><tr><td><code>MAX_INDEX_ATTEMPTS</code></td><td><code>8</code></td><td>Failed attempts before an email is left out of search</td></tr></tbody></table><h3 id="tuning-ingestion-concurrency" tabindex="-1">Tuning ingestion concurrency <a class="header-anchor" href="#tuning-ingestion-concurrency" aria-label="Permalink to &quot;Tuning ingestion concurrency&quot;">​</a></h3><p>Two settings, one across mailboxes and one within a mailbox, and they multiply.</p><p><code>INGESTION_WORKER_CONCURRENCY</code> is how many mailboxes sync at the same time. Increase it on servers with more RAM to reduce total sync time.</p><p><code>INGESTION_EMAIL_CONCURRENCY</code> is how many emails one mailbox archives at the same time. Archiving an email is a download followed by a storage write and a handful of database writes; run strictly one at a time, the connector idles through every write and the writes idle through every download. This overlaps them, and it is the setting to raise when a single large mailbox is the thing taking all night.</p><p>Deduplication stays correct regardless of the value: messages sharing a Message-ID are serialised within the mailbox, so the check-then-insert dedup gate never runs against itself. Sources with <strong>Preserve Original File</strong> (GoBD) enabled also dedup on a content hash, which is what catches byte-identical messages whose Message-ID is missing — those have no shared key to serialise on, so in that mode every message without a Message-ID is processed one at a time instead.</p><p>The two multiply for memory: a worker can hold <code>INGESTION_WORKER_CONCURRENCY</code> × <code>INGESTION_EMAIL_CONCURRENCY</code> emails&#39; attachment buffers at once, and unlike the indexing worker this process runs without a heap ceiling. Raise in small steps.</p><h3 id="tuning-indexing-memory" tabindex="-1">Tuning indexing memory <a class="header-anchor" href="#tuning-indexing-memory" aria-label="Permalink to &quot;Tuning indexing memory&quot;">​</a></h3><p>Two settings look similar and do different jobs.</p><p><code>MEILI_INDEXING_CHUNK</code> is the memory dial. Building a document reads the whole <code>.eml</code> from storage, parses it, and extracts the text of every attachment, so this is the number of those that are resident at once. It is what to reduce when the indexing worker is under memory pressure — a deployment with large attachments may want 10 or less.</p><p><code>MEILI_INDEXING_BATCH</code> is queue granularity: how many email ids travel in one job. It does <strong>not</strong> drive memory, because a job processes its ids one chunk at a time. It does drive self-healing throughput, since the reconcile pass enqueues at most <code>INDEX_RECONCILE_PAGE_CAP</code> <strong>jobs</strong> per tick — so lowering it lowers how fast a backlog drains.</p><p><code>INDEXING_WORKER_CONCURRENCY</code> is how many jobs run at once, and it is usually the setting that decides throughput. Most of a job&#39;s wall clock is spent waiting rather than computing: a storage read per email, then a Meilisearch task the job must see finish before it may mark those emails indexed. Left at one job at a time — the previous behaviour — that wait was dead time, and a backlog drained at a fixed rate no matter how large the host was.</p><p><code>INDEXING_WORKER_MAX_OLD_SPACE_MB</code> (default <code>2048</code>) sets the worker&#39;s V8 heap ceiling. An explicit limit makes V8 collect harder as it approaches the limit rather than sizing itself from host RAM.</p><p>Peak indexing memory has two terms:</p><ul><li><strong>Built documents</strong> — roughly <code>INDEXING_WORKER_CONCURRENCY</code> × 2 × <code>MEILI_INDEXING_CHUNK</code> × <code>INDEXING_MAX_TEXT_BYTES</code>. The factor of two is the pipeline: while one chunk&#39;s write is settling at Meilisearch, the next chunk is already being built.</li><li><strong>Raw buffers</strong> — the <code>.eml</code> and attachment bytes of the documents currently being built, each fully in memory while it is parsed and its text extracted. This is bounded process-wide rather than per job: the per-job build pool is divided by <code>INDEXING_WORKER_CONCURRENCY</code>, so about ten documents build at once whatever the concurrency, and raising the concurrency does not multiply this term.</li></ul><p>When raising concurrency, raise the heap ceiling or lower the chunk to match the first term. Both settings are capped at 32; a value above that, or one that is not a plain integer (<code>1_000</code>, <code>10k</code>), is rejected with a warning and the default used instead.</p><h2 id="resilience" tabindex="-1">Resilience <a class="header-anchor" href="#resilience" aria-label="Permalink to &quot;Resilience&quot;">​</a></h2><ul><li><strong>Job retries:</strong> All jobs are configured with 5 retry attempts using exponential backoff (starting at 1 second). This handles transient API failures from email providers.</li><li><strong>Worker crash recovery:</strong> BullMQ detects stalled jobs (no heartbeat within <code>lockDuration</code>) and re-queues them automatically. On retry, already-processed emails are skipped via <code>checkDuplicate()</code>.</li><li><strong>Partial sync recovery:</strong> Stale session detection handles the case where a worker crashes mid-dispatch, leaving some mailboxes never enqueued. The source is reset to <code>error</code> and the next scheduler tick retries the full sync.</li></ul>`,41)]))}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
